//! `Config` -> odhcpd configuration in UCI syntax (`/etc/config/dhcp`).
//!
//! odhcpd reads UCI through libuci and resolves interface names via ubus, which this
//! system does not have; see the README for that known phase-2 gap. We emit both
//! `interface` and `ifname` so that a build of odhcpd that understands either can
//! pick the bridge up.

use std::path::Path;

use owr_config::{Config, LanIpv6};

use crate::topology::LAN_BRIDGE;

pub(crate) fn render_odhcpd(cfg: &Config, run_dir: &Path) -> String {
    let mut l = vec![
        "# Generated by owr-apply. Do not edit; changes are overwritten.".to_owned(),
        "config odhcpd 'odhcpd'".to_owned(),
        "\toption maindhcp '0'".to_owned(),
        format!("\toption leasefile '{}/odhcpd.leases'", run_dir.display()),
        "\toption loglevel '4'".to_owned(),
    ];
    if cfg.network.lan.ipv6 == LanIpv6::Ula {
        l.extend([
            String::new(),
            "config dhcp 'lan'".to_owned(),
            "\toption interface 'lan'".to_owned(),
            format!("\toption ifname '{LAN_BRIDGE}'"),
            "\toption ra 'server'".to_owned(),
            "\toption dhcpv6 'server'".to_owned(),
            "\toption ra_flags 'managed-config other-config'".to_owned(),
            "\toption ndp 'disabled'".to_owned(),
        ]);
    }
    let mut text = l.join("\n");
    text.push('\n');
    text
}
